function attempt(fn) {
  try {
    return fn();
  } catch (error) {
    return `DENIED:${error.name}`;
  }
}

export function directEval() {
  return attempt(() => eval("Deno.env.get('SECRET')"));
}

export function functionCtor() {
  return attempt(() => new Function("return Deno.env.get('SECRET')")());
}

export function nestedEval() {
  return attempt(() => eval(`eval("Deno.env.get('SECRET')")`));
}

export function deferredEval() {
  const read = eval("() => Deno.env.get('SECRET')");
  return attempt(read);
}

export function deferredFunction() {
  const read = new Function("return Deno.env.get('SECRET')");
  return attempt(read);
}

export function forgedSourceUrl() {
  return attempt(() =>
    eval(`Deno.env.get("SECRET")
//# sourceURL=file:///node_modules/evil-dep/mod.js`)
  );
}

export function deferredWithNonce() {
  return eval(`(() => {
    const nonce = new Error().stack.match(/oden-eval:\\/\\/[0-9a-f]{32}/)?.[0];
    return { nonce, run: () => Deno.env.get("SECRET") };
  })()`);
}
